import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for eid in [1, 2, 4, 5]:
    dfs[f'e{eid}'] = pd.read_csv(f'experiment_{eid}_csv')
    print(f"\n=== Experiment {eid} ===")
    print(dfs[f'e{eid}'].describe().round(2))
    print("\nColumns:", list(dfs[f'e{eid}'].columns))
    if 'FeedWaterFlowRate' in dfs[f'e{eid}'].columns:
        print("Flow rate values:", dfs[f'e{eid}']['FeedWaterFlowRate'].unique()[:5])

# Combine all data where we have key variables
all_data = []
for eid, df in dfs.items():
    if 'ProductTiter' in df.columns:
        row = df.iloc[0]  # take representative row
        entry = {'exp': eid, 'ProductTiter': row['ProductTiter']}
        for col in df.columns:
            if col != 'ProductTiter' and df[col].dtype in ['float64', 'int64']:
                entry[col] = row[col]
        all_data.append(entry)

combined = pd.DataFrame(all_data)
print("\n=== COMBINED ACROSS EXPERIMENTS ===")
print(combined)

# Check correlations
if 'Osmolality' in combined.columns:
    print("\nCorr(Osmolality, Titer):", np.corrcoef(combined['Osmolality'], combined['ProductTiter'])[0,1])
if 'FeedWaterFlowRate' in combined.columns:
    print("Corr(FlowRate, Titer):", np.corrcoef(combined['FeedWaterFlowRate'], combined['ProductTiter'])[0,1])
